arguments.command:
SYMFILE="/tmp/symbols/mono.so"
# Use nm to find closest named symbol for those addresses
nm --defined-only "$SYMFILE" 2>/dev/null | sort | awk '
/^[0-9a-f]+ [tTwW]/ { addrs[NR]=$1; names[NR]=$3 }
END {
  targets["2f4b20"]=1; targets["2f4c84"]=1
  for (t in targets) {
    best=""; bestaddr=""
    for (i in addrs) {
      if (addrs[i] <= t && addrs[i] > bestaddr) { bestaddr=addrs[i]; best=names[i] }
    }
    print t " -> " best " (+" sprintf("0x%x", strtonum("0x"t) - strtonum("0x"bestaddr)) ")"
  }
}' | head -10

# Alternative: just check what function contains these
echo "---"
llvm-addr2line-18 -f -e "$SYMFILE" 0x2f4b20 0x2f4c84

